css:
.sec{position:relative; overflow:hidden}
.bgword{position:absolute; top:-48px; left:0; z-index:0;
  font-size:clamp(64px,11vw,120px); font-weight:800; line-height:1;
  letter-spacing:.02em; white-space:nowrap;
  color:#2a2a2a}            /* 地#111との明度差は3〜8%だけ。読ませない */
.sec > .card, .sec > figure{position:relative; z-index:1}

/* 筆記体・淡色版（明るい地の上） */
.eyebrow{position:absolute; top:40px; left:0; z-index:0;
  font-family:'Tangerine',cursive; font-size:clamp(64px,9vw,120px);
  line-height:.95; color:#e7dcc6}
.photo{position:relative; z-index:1}
